/** p5.brush ships no type declarations; the standalone build (WebGL2, no p5) is typed loosely here. */
declare module "p5.brush/standalone" {
  export const DEGREES: string;
  export const RADIANS: string;
  export function createCanvas(width: number, height: number, options?: Record<string, unknown>): HTMLCanvasElement;
  export function load(canvas?: HTMLCanvasElement | OffscreenCanvas): void;
  export function render(): void;
  export function clear(color?: string | number, g?: number, b?: number): void;
  export function push(): void;
  export function pop(): void;
  export function translate(x: number, y: number): void;
  export function rotate(angle: number): void;
  export function scale(x: number, y?: number): void;
  export function angleMode(mode: string): void;
  export function seed(n: number): void;
  export function noiseSeed(n: number): void;
  export function scaleBrushes(scale: number): void;
  export function box(): string[];
  export function add(name: string, params: Record<string, unknown>): void;
  export function set(name: string, color: string | number[], weight?: number): void;
  export function pick(name: string): void;
  export function stroke(...args: (string | number | number[])[]): void;
  export function noStroke(): void;
  export function strokeWeight(weight: number): void;
  export function fill(...args: (string | number | number[])[]): void;
  export function noFill(): void;
  export function wash(color: string, opacity?: number): void;
  export function noWash(): void;
  export function fillBleed(strength: number, direction?: string, angle?: number): void;
  export function fillTexture(textureStrength: number, borderIntensity: number, scatter?: boolean): void;
  export function hatch(dist: number, angle: number, options?: Record<string, unknown>): void;
  export function noHatch(): void;
  export function hatchStyle(name: string, color: string | number[], weight?: number): void;
  export function mass(...args: unknown[]): void;
  export function noMass(): void;
  export function field(name: string): void;
  export function noField(): void;
  export function addField(name: string, fn: (t: number, field: number[][]) => number[][], options?: Record<string, unknown>): void;
  export function line(x1: number, y1: number, x2: number, y2: number): void;
  export function flowLine(x: number, y: number, length: number, dir: number): void;
  export function rect(x: number, y: number, w: number, h: number, mode?: string): void;
  export function circle(x: number, y: number, r: number, r2?: boolean): void;
  export function arc(x: number, y: number, r: number, start: number, end: number): void;
  export function polygon(points: [number, number][]): void;
  export function beginShape(curvature?: number): void;
  export function vertex(x: number, y: number, pressure?: number): void;
  export function endShape(close?: string | boolean): void;
  export function spline(points: [number, number][], curvature?: number): void;
  export function clip(region: [number, number, number, number]): void;
  export function noClip(): void;
}
